contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: attempt withdrawAll from either owner or non-owner depending on caller.
    // Parameters:
    //   callerIsOwner: when true, the test caller is intended to be the owner address stored in c; when false, it's a different address.
    //   sendValue: amount of wei to send into c via fallback before the withdraw test (so there is a balance to withdraw).
    // Note: the test runs in the context of this contract. To simulate being the owner we rely on the fact
    // that in the original contract C the owner was set to its deployer; the test user must deploy C with
    // this test's deployer such that c.owner==address(this) when callerIsOwner=true. The property compares
    // observable revert behavior of withdrawAll against the boolean callerIsOwner.
    function run(bool callerIsOwner, uint sendValue) public payable {
        // ensure this contract has enough balance to forward sendValue
        require(address(this).balance >= sendValue);

        // First, fund C so there is something to withdraw
        // Use low-level call to invoke fallback and increase depositsCount
        (bool s,) = address(c).call{value: sendValue}("");
        require(s);

        // Decide whose call we're simulating: if callerIsOwner==true, we expect withdrawAll to succeed when
        // msg.sender == owner. To make the call in that role, this contract must be the owner stored in c.
        // We attempt the call and capture whether it reverts.
        bool didRevert;
        // perform the call and catch revert via low-level call
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        didRevert = !ok;

        // The rule: withdrawAll reverts iff the caller is NOT the owner. That is, didRevert == (!callerIsOwner)
        // This holds for the original contract C, and is violated by the mutant which inverts the ownership check.
        assert(didRevert == (!callerIsOwner));
    }

    // allow the contract to receive ETH so the test runner can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed: property should hold for all callers.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // General rule: if msg.sender is not the owner, withdrawAll should revert.
        // We cannot read owner directly, so express the rule as: either the call reverted,
        // or it was made by the owner. This enforces that non-owners cannot succeed.
        // That is, success implies caller is owner. Since we cannot call c.owner() here
        // if it were non-public, we instead rely on the observable behavior: success
        // only allowed when msg.sender==owner; encode as reverted || (address(this).balance == address(this).balance);
        // But we must reference only parameters and revert flag; express as reverted || true would be trivial.
        // Instead directly require that if the call did not revert, then msg.sender must be the owner.
        // We can observe owner via the public getter c.owner().
        address ownerAddr = c.owner();
        assert(reverted || msg.sender == ownerAddr);
    }
    receive() external payable {}
}

