contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence:
    // 1) nonOwnerDepositAmount is sent to c via fallback to increase its balance
    // 2) a non-owner attempts to withdraw some amount by calling withdraw
    // On original contract P this withdraw reverts (onlyOwner), so c's balance stays >= prior balance.
    // On mutant M withdraw succeeds and balance can decrease; our assert checks balance did not decrease.

    function runTest(address nonOwner, uint nonOwnerDepositAmount, uint withdrawAmount) public {
        // preconditions for the test environment
        require(nonOwner != address(0));
        require(nonOwner != address(this));
        require(nonOwnerDepositAmount > 0);
        require(address(this).balance >= nonOwnerDepositAmount);

        uint before = address(c).balance;

        // send deposit into c from this contract, but the fallback increments depositsCount and increases balance
        // we must forward the call from this contract; simulate as this contract being the sender
        (bool sent, ) = address(c).call{value: nonOwnerDepositAmount}("");
        require(sent);

        uint afterDeposit = address(c).balance;
        // ensure deposit had effect
        require(afterDeposit == before + nonOwnerDepositAmount);

        // Attempt withdraw as nonOwner by invoking c.withdraw from this contract but specifying tx.origin-like actor is not possible.
        // To simulate a non-owner caller, we call via delegatecall is forbidden; instead we use the provided nonOwner address
        // by asking c to sendMoney to trigger an external call originating from c. However the changed modifier affects withdraw/sendMoney.
        // We therefore attempt to have nonOwner call withdraw by using low-level call to c with from=nonOwner is not possible here.
        // Instead, we let nonOwner be externally the msg.sender: require nonOwner == address(this) is false, so we instead
        // use c.sendMoney to make c send funds to nonOwner if sendMoney is callable by non-owner in mutant. But original restricts it.

        // We perform the critical state-changing call: try to withdraw funds by invoking c.withdraw(withdrawAmount) via a low-level call
        // where msg.sender will be THIS contract. If THIS is not the owner of c, this call should revert on P and succeed on M.
        // Ensure this contract is not the owner by checking getter: owner() should not equal address(this)
        address owner = c.owner();
        require(owner != address(this));

        // The deciding call: attempt to withdraw from c as a non-owner (this contract)
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));

        // After attempt, check that balance did not decrease (on P withdraw reverts so balance stays the same; on M it can decrease)
        uint finalBal = address(c).balance;

        // GENERAL ASSERTION: contract balance must be at least afterDeposit (i.e., non-owner call did not cause funds to be withdrawn)
        assert(finalBal >= afterDeposit);
    }

    // allow this contract to receive ETH for funding test deposits
    receive() external payable {}
}

